import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/IF.md","filePath":"manual-en/IF.md","lastUpdated":1785684581000}'),i={name:"manual-en/IF.md"};function n(r,e,d,c,p,l){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h3 id="_12-6-if" tabindex="-1">12.6 IF <a class="header-anchor" href="#_12-6-if" aria-label="Permalink to &quot;12.6 IF&quot;">​</a></h3><pre><code>IF condition variable=expression.
</code></pre><p>or</p><pre><code>IF condition vector(index)=expression.
</code></pre><p>The <code>IF</code> transformation conditionally assigns the value of a target expression to a target variable, based on the truth of a test expression.</p><p>Specify a boolean-valued expression (see <a href="./Expressions">Expressions</a>) to be tested following the <code>IF</code> keyword. This expression is evaluated for each case. If the value is true, then the value of the expression is computed and assigned to the specified variable. If the value is false or missing, nothing is done. Numeric and string variables may be assigned. When a string expression’s width differs from the target variable’s width, the string result of the expression is truncated or padded with spaces on the right as necessary. The expression and variable types must match.</p><p>The target variable may be specified as an element of a vector (see <a href="./VECTOR">VECTOR</a>). In this case, a vector index expression must be specified in parentheses following the vector name. The index expression must evaluate to a numeric value that, after rounding down to the nearest integer, is a valid index for the named vector.</p><p>Using <code>IF</code> to assign to a variable specified on <code>LEAVE</code> (see <a href="./LEAVE">LEAVE</a>) resets the variable’s left state. Therefore, <code>LEAVE</code> should be specified following <code>IF</code>, not before.</p><p>When <code>IF</code> is specified following <code>TEMPORARY</code> (see <a href="./TEMPORARY">TEMPORARY</a>), the <code>LAG</code> function may not be used (see <a href="./Miscellaneous-Functions#LAG">LAG</a>).</p>`,9)])])}const u=a(i,[["render",n]]);export{f as __pageData,u as default};
